import './App_Country.css';
import React, { Component } from 'react';
import CountryTable from './components/CountryTable';
import CountryAdd from './components/CountryAdd';
import CountryFilter from './components/CountryFilter';

class App extends Component {
    constructor(props) {
        super(props);
        this.state = {
            countries: [
                { name: "India", capital: "New Delhi" },
                { name: "USA", capital: "Washington D.C." }
            ]
        };
    }

    addCountry = (newCountry) => {
        this.setState({
            countries: [...this.state.countries, newCountry]
        });
    };

    render() {
        return (
            <div className="App">
                <h1>Country Tracker</h1>

                <CountryFilter />
                <hr />

                <CountryTable countries={this.state.countries} />
                <hr />

                <CountryAdd addCountry={this.addCountry} />
            </div>
        );
    }
}

export default App;
